UPDATE t_generation_task
SET deleted    = 1,
    deleted_at = CURRENT_TIMESTAMP(3),
    updated_at = CURRENT_TIMESTAMP(3)
WHERE task_type = #{type}
  AND id = #{id}
  AND deleted = 0

  AND user_id = #{userId}

mapper.select:
SELECT 
FROM t_generation_task

    task_type = 'VIDEO' AND deleted = 0

        AND user_id = #{userId}


        AND status = #{status}


        AND model_code = #{modelCode}


        AND prompt LIKE CONCAT('%', #{keyword}, '%')


ORDER BY id DESC

SELECT FROM t_generation_task WHERE task_type = 'VIDEO' AND deleted = 0 AND provider_task_id IS NOT NULL AND status IN
#{s}
ORDER BY id

SELECT COUNT(*) AS total_count, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN 1 ELSE 0 END), 0) AS succeeded_count, COALESCE(SUM(CASE WHEN status IN () THEN 1 ELSE 0 END), 0) AS failed_count, COALESCE(SUM(CASE WHEN status IN () THEN 1 ELSE 0 END), 0) AS in_progress_count, COALESCE(SUM(total_cost), 0) AS total_cost, COALESCE(SUM(video_cost), 0) AS total_video_cost, COALESCE(SUM(llm_cost), 0) AS total_llm_cost, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN billed_duration ELSE 0 END), 0) AS total_video_seconds, AVG(CASE WHEN status = 'SUCCEEDED' THEN total_cost END) AS avg_cost, AVG(CASE WHEN status = 'SUCCEEDED' THEN total_elapsed_ms END) AS avg_elapsed_ms FROM t_generation_task
task_type = 'VIDEO'
AND user_id = #{userId}

SELECT COUNT(*) AS total_count, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN 1 ELSE 0 END), 0) AS succeeded_count, COALESCE(SUM(CASE WHEN status IN ('FAILED', 'CANCELED', 'TIMEOUT') THEN 1 ELSE 0 END), 0) AS failed_count, COALESCE(SUM(CASE WHEN status IN ('SUBMITTING', 'RUNNING') THEN 1 ELSE 0 END), 0) AS in_progress_count, COALESCE(SUM(CASE WHEN status = 'SUCCEEDED' THEN image_count ELSE 0 END), 0) AS total_images, COALESCE(SUM(total_cost), 0) AS total_cost, COALESCE(SUM(image_cost), 0) AS total_image_cost, COALESCE(SUM(llm_cost), 0) AS total_llm_cost, AVG(CASE WHEN status = 'SUCCEEDED' THEN total_cost END) AS avg_cost, AVG(CASE WHEN status = 'SUCCEEDED' THEN total_elapsed_ms END) AS avg_elapsed_ms FROM t_generation_task
task_type = 'IMAGE'
AND user_id = #{userId}
